/**
 * Notification request schemas.
 *
 * Deliberately thin: nothing about a notification is client-supplied except
 * how many to fetch. Everything else — recipient, type, the service it
 * concerns — is server-generated by `notificationService` at the moment the
 * underlying event happens, never accepted from a request body (the same
 * mass-assignment reasoning SRS 22.4 applies to a service).
 */
import { z } from 'zod';

export const DEFAULT_NOTIFICATION_LIMIT = 20;
export const MAX_NOTIFICATION_LIMIT = 50;

export const notificationListQuerySchema = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(MAX_NOTIFICATION_LIMIT)
    .default(DEFAULT_NOTIFICATION_LIMIT),
});

export type NotificationListQuery = z.output<typeof notificationListQuerySchema>;

/** An empty strict body — `POST .../read` accepts nothing to override. */
export const markNotificationReadSchema = z.strictObject({});
